/**
 * This test verifies whether short-circuit socket path parent directory configurations
 * are skipped for coordinator-only mode instances and checked for executors. A socket
 * directory is created in order to mock the file access.
 */
@Test
public void testCheckShortCircuitConfigs() {
    String tmpDir = System.getProperty("java.io.tmpdir", "/tmp");
    File socketDir = new File(tmpDir + "/socketTest", "socks." + (System.currentTimeMillis() + "." + (new Random().nextInt())));
    socketDir.mkdirs();
    socketDir.getParentFile().setExecutable(false);
    Configuration conf = mock(Configuration.class);
    when(conf.getBoolean(HdfsClientConfigKeys.Read.ShortCircuit.KEY, HdfsClientConfigKeys.Read.ShortCircuit.DEFAULT)).thenReturn(true);
    when(conf.getTrimmed(HdfsClientConfigKeys.DFS_DOMAIN_SOCKET_PATH_KEY, HdfsClientConfigKeys.DFS_DOMAIN_SOCKET_PATH_DEFAULT)).thenReturn(socketDir.getAbsolutePath());
    when(conf.getBoolean(HdfsClientConfigKeys.DFS_CLIENT_USE_LEGACY_BLOCKREADERLOCAL, HdfsClientConfigKeys.DFS_CLIENT_USE_LEGACY_BLOCKREADERLOCAL_DEFAULT)).thenReturn(false);
    BackendConfig.INSTANCE = mock(BackendConfig.class);
    when(BackendConfig.INSTANCE.isDedicatedCoordinator()).thenReturn(true);
    String actualErrorMessage = JniFrontend.checkShortCircuitRead(conf);
    assertEquals("", actualErrorMessage);
    when(BackendConfig.INSTANCE.isDedicatedCoordinator()).thenReturn(false);
    actualErrorMessage = JniFrontend.checkShortCircuitRead(conf);
    assertEquals("Invalid short-circuit reads configuration:\n" + "  - Impala cannot read or execute the parent directory of " + HdfsClientConfigKeys.DFS_DOMAIN_SOCKET_PATH_KEY + "\n", actualErrorMessage);
    if (socketDir != null) {
        socketDir.getParentFile().setExecutable(true);
        socketDir.delete();
        socketDir.getParentFile().delete();
    }
}

